def swap_values_in_hex(h):
    vals = set(c for row in h for c in row)
    if len(vals) == 1:
        return h
    sorted_vals = sorted(vals)
    v_low, v_high = sorted_vals
    new_h = [[v_high if x == v_low else v_low for x in row] for row in h]
    return new_h

